head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vViewYn = '';
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(panel_1);
        // 파라미터설정
        scwin.setParam();
        if (txb_IsurCd.getValue() !== '') scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90003.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90003.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90003.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        if (scwin.vViewYn === 'Y') return;
        await scwin.setParStkcertIsu('N');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90003.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90003.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90003.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name txb_IsurCd_onkeypress
 * @description txb_IsurCd onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurCd_onkeypress = function() {
    try {
        if (window.event.keyCode === 13) scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90003.txb_IsurCd_onkeypress" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description 주권종목 데이터를 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    let param = '';
    param += "&{P}V_ISU_CD_NM=";
    param += "&{P}V_ISUR_CD=" + txb_IsurCd.getValue();
    const dsNm = 'BNS_STKCERT_INFO';
    const qryId = 'lds.stf.bnscommon.select.listStkcertIsuCd';
    $c.bns.fn_SearchBns("ULDBNS90003.xml", dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        let arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        txb_IsurCd.setValue(arrPar[0].ISUR_CD);
        if (arrPar[0].POP_CALL_YN !== 'undefined') {
            scwin.vViewYn = arrPar[0].POP_CALL_YN;
        } else if (arrPar[0].DELETE_YN !== 'undefined') {
            scwin.vViewYn = arrPar[0].DELETE_YN;
        }
    }
};

/**
 * @method
 * @name setParStkcertIsu
 * @description 부모창에 보낼 데이터를 설정한다.
 * @param {String} delYn delYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParStkcertIsu = async function(delYn) {
    let arrPar = new Array();
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), "STD_CD"),
        ISU_NM: dts_List.getCellData(dts_List.getRowPosition(), "ISU_NM"),
        ISUR_CD: dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD"),
        DELETE_YN: delYn
    };
    scwin.fn_SetPar(arrPar);
    await $c.win.closePopup();
};
